from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import unquote, urlsplit
import json

root = Path('/tmp/plato-mlx-docs-site')
pages = ['mlx/index.html', 'install/index.html', 'quickstart/index.html',
         'development/index.html', 'configurations/trainer/index.html',
         'references/trainers/index.html']
class Document(HTMLParser):
    def __init__(self, path):
        super().__init__()
        self.links, self.ids = [], set()
        self.feed(path.read_text())
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if attrs.get('id'): self.ids.add(attrs['id'])
        if tag == 'a' and attrs.get('href'): self.links.append(attrs['href'])

checked = 0
errors = []
for page in pages:
    path = root / page
    doc = Document(path)
    for href in doc.links:
        parsed = urlsplit(href)
        if parsed.scheme or parsed.netloc: continue
        if not parsed.path: target = path
        elif parsed.path.startswith('/'): target = root / unquote(parsed.path).lstrip('/')
        else: target = path.parent / unquote(parsed.path)
        target = target.resolve()
        if target.is_dir(): target /= 'index.html'
        checked += 1
        if not target.exists(): errors.append([page, href, 'missing target'])
        elif parsed.fragment and target.suffix == '.html':
            if unquote(parsed.fragment) not in Document(target).ids:
                errors.append([page, href, 'missing anchor'])
result = {'pages': pages, 'local_links_checked': checked, 'errors': errors,
          'external_links': 'Not fetched; no new external links introduced.'}
print(json.dumps(result, indent=2))
Path('/tmp/plato-mlx-docs-validation/links.json').write_text(json.dumps(result, indent=2)+'\n')
raise SystemExit(bool(errors))
